// ═══════════════════════════════════════════════════════════════
// NODE: UNIVERSAL DATA NORMALIZATION
// Handles all 3 trigger sources. Cleans data, fills missing
// fields with safe defaults, normalizes enums, computes SLA.
// ═══════════════════════════════════════════════════════════════

const raw = $input.first().json;

// ── Utility helpers ──────────────────────────────────────────
const safeStr  = (v, fb='') => v == null ? fb : String(v).trim().replace(/<[^>]*>/g,'');
const safeArr  = (v) => Array.isArray(v) ? v : typeof v==='string' ? v.split(/[,;|]/).map(s=>s.trim()).filter(Boolean) : ['unknown-service'];
const safeParse= (v) => { if(!v) return {}; if(typeof v==='object') return v; try{return JSON.parse(v);}catch{return {};} };
const genId    = () => `TKT-${Date.now()}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;

// ── Severity map ─────────────────────────────────────────────
const SEV_MAP = {
  critical:'CRITICAL', p0:'CRITICAL', sev0:'CRITICAL', '1':'CRITICAL',
  high:'HIGH', p1:'HIGH', sev1:'HIGH', '2':'HIGH', error:'HIGH', failure:'HIGH',
  medium:'MEDIUM', p2:'MEDIUM', sev2:'MEDIUM', '3':'MEDIUM', warning:'MEDIUM',
  low:'LOW', p3:'LOW', sev3:'LOW', '4':'LOW',
  info:'INFO', p4:'INFO', '5':'INFO'
};
const normSev = (v) => SEV_MAP[String(v||'').toLowerCase()] || 'MEDIUM';

// ── Category inference ────────────────────────────────────────
const CAT_KW = [
  ['DEPLOYMENT',      ['deploy','release','rollout','workflow_run','build','ci','cd','pipeline']],
  ['INFRASTRUCTURE',  ['infra','k8s','kubernetes','pod','node','cluster','vm','server']],
  ['SECURITY',        ['security','cve','vuln','auth','ssl','tls','cert','breach','hack']],
  ['PERFORMANCE',     ['perf','latency','slow','timeout','memory','cpu','throttle','p99']],
  ['DATABASE',        ['database','db','sql','postgres','mysql','mongo','redis','query']],
  ['NETWORK',         ['network','dns','connect','unreachable','503','502','gateway']],
  ['APPLICATION',     ['app','bug','exception','crash','500','error','complaint']]
];
const inferCat = (raw, desc) => {
  const hit = CAT_KW.find(([,kws]) => kws.includes(String(raw||'').toLowerCase()));
  if (hit) return hit[0];
  const text = String(desc||'').toLowerCase();
  for (const [cat,kws] of CAT_KW) if (kws.some(k=>text.includes(k))) return cat;
  return 'APPLICATION';
};

// ── Detect source from payload shape ─────────────────────────
const detectSource = (r) => {
  if (r.workflow_run || r.repository || r.check_run || r.ref) return 'GITHUB';
  if (r.alert_type || r.alert_key || r.dd_status || r.incident_id) return 'MONITORING';
  return 'MANUAL';
};

const source = detectSource(raw);
let title, description, rawSeverity, rawCategory, services, environment, reporter, meta;

// ── Per-source field extraction ───────────────────────────────
if (source === 'GITHUB') {
  const repo = raw.repository?.full_name || raw.repository?.name || 'unknown-repo';
  const run  = raw.workflow_run || {};
  const conc = run.conclusion || 'failure';
  title       = `[CI/CD] ${run.name || 'Workflow'} ${conc.toUpperCase()} — ${repo}`;
  description = `Branch: ${run.head_branch||'?'} | Commit: ${run.head_commit?.message||'N/A'} | Run: ${run.html_url||'#'}`;
  rawSeverity = conc === 'failure' ? 'HIGH' : 'MEDIUM';
  rawCategory = 'DEPLOYMENT';
  services    = [repo.split('/')[1] || repo];
  environment = (run.head_branch === 'main' || run.head_branch === 'master') ? 'production' : 'staging';
  reporter    = { name: raw.sender?.login||'GitHub Actions', email:'github-actions@company.com', team:'platform-eng' };
  meta        = { github_run_id: run.id, github_run_url: run.html_url, head_sha: run.head_sha };

} else if (source === 'MONITORING') {
  title       = safeStr(raw.title || raw.alert_title || raw.monitor_name, 'Monitoring Alert');
  description = safeStr(raw.message || raw.body || raw.alert_message, '');
  rawSeverity = raw.severity || raw.priority || raw.alert_severity;
  rawCategory = raw.type || raw.alert_type || raw.category;
  services    = safeArr(raw.service || raw.affected_services);
  environment = safeStr(raw.env || raw.environment, 'production');
  reporter    = { name: raw.source||'Monitoring', email:'alerts@company.com', team:'sre' };
  meta        = { alert_id: raw.id||raw.alert_id, alert_url: raw.url||raw.alert_url };

} else {
  // MANUAL complaint form — most fields may be missing → safe defaults
  title       = safeStr(raw.title || raw.subject || raw.summary, '');
  description = safeStr(raw.description || raw.body || raw.message || raw.complaint, 'No description provided');
  rawSeverity = raw.severity || raw.priority || raw.urgency;
  rawCategory = raw.category || raw.type || raw.issue_type;
  services    = safeArr(raw.affected_services || raw.services || raw.service);
  environment = safeStr(raw.environment || raw.env, 'production').toLowerCase();
  reporter    = {
    name:  safeStr(raw.reporter_name  || raw.name  || raw.user, 'Anonymous User'),
    email: safeStr(raw.reporter_email || raw.email,             'unknown@company.com'),
    team:  safeStr(raw.team           || raw.squad,             'unknown')
  };
  meta = { form_submission: true, submitted_at: raw.submitted_at || raw.created_at };
}

// ── MISSING DATA HANDLING ─────────────────────────────────────
// Track which fields were auto-filled so Jira/Slack can flag them
const missing = [];
if (!title)                              { missing.push('title');       title = `[${source}] Untitled Incident ${genId().slice(-6)}`; }
if (!description || description.length<5){ missing.push('description'); }
if (!rawSeverity)                        { missing.push('severity');    }
if (!rawCategory)                        { missing.push('category');    }
if (!services || services[0]==='unknown-service') { missing.push('services'); }

const severity = normSev(rawSeverity);
const category = inferCat(rawCategory, `${title} ${description}`);

// ── SLA + escalation deadlines ────────────────────────────────
const SLA_H = { CRITICAL:1, HIGH:4, MEDIUM:24, LOW:72, INFO:168 };
const slaMs  = (SLA_H[severity]||24)*3600000;
const now    = Date.now();

const cleaned = {
  ticket_id:           genId(),
  title,
  description,
  source,
  severity,
  category,
  environment,
  region:              safeStr(raw.region   || meta.region,    'us-east-1'),
  cluster:             safeStr(raw.cluster  || meta.cluster,   'prod-cluster'),
  namespace:           safeStr(raw.namespace|| meta.namespace, 'default'),
  affected_services:   services,
  reporter,
  status:              'OPEN',
  reported_at:         raw.reported_at || raw.created_at || new Date().toISOString(),
  ingested_at:         new Date().toISOString(),
  sla_deadline:        new Date(now + slaMs).toISOString(),
  escalation_deadline: new Date(now + 30*60000).toISOString(),
  metadata:            { ...meta, missing_fields: missing, execution_id: $execution.id },
  data_quality: {
    missing_fields:     missing,
    completeness_score: Math.round(((5 - missing.length) / 5) * 100)
  }
};

return [{ json: cleaned }];

// Merge knowledge base search results with the cleaned ticket.
// Build a readable KB context string for the AI prompt.

const ticket = $input.first().json;
let kbItems  = [];

try {
  const resp = ticket; // HTTP response is merged into same item
  kbItems = resp.similar_incidents || resp.results || [];
} catch { kbItems = []; }

const kbContext = kbItems.length > 0
  ? kbItems.slice(0,3).map((inc, i) =>
      `[${i+1}] "${inc.title}" | Fix: ${inc.applied_fix || inc.resolution_summary || 'N/A'}`
    ).join('\n')
  : 'No similar past incidents found.';

return [{ json: { ...ticket, kb_similar: kbItems, kb_context: kbContext } }];

// ═══════════════════════════════════════════════════════════════
// NODE: AI RESULT MERGE + FALLBACK
// If Claude API fails or returns malformed JSON, we use
// rule-based fallback so the workflow never breaks.
// ═══════════════════════════════════════════════════════════════

const ticket = $input.first().json;
let ai = {};

try {
  const raw = ticket.analysis || ticket.body || ticket;
  ai = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (ai.analysis) ai = ai.analysis; // unwrap nested
} catch { ai = {}; }

// Rule-based priority scores as fallback
const SEV_SCORE = { CRITICAL:95, HIGH:75, MEDIUM:45, LOW:20, INFO:5 };

const enriched = {
  ...ticket,
  ai: {
    summary:                    ai.summary                    || `${ticket.category} incident in ${ticket.environment}. Immediate triage required.`,
    priority_score:             ai.priority_score             || SEV_SCORE[ticket.severity] || 50,
    recommended_team:           ai.recommended_team           || 'platform-sre',
    root_cause_hypothesis:      ai.root_cause_hypothesis      || 'Root cause under investigation. Check recent deployments and error logs.',
    recommended_actions:        ai.recommended_actions        || ['Check service logs','Review recent deploys','Monitor error rates','Page on-call if degrading'],
    requires_rollback:          Boolean(ai.requires_rollback),
    rollback_target:            ai.rollback_target            || '',
    rollback_confidence:        ai.rollback_confidence        || 0,
    escalate_to_oncall:         Boolean(ai.escalate_to_oncall) || ticket.severity === 'CRITICAL',
    estimated_resolution_min:   ai.estimated_resolution_min  || 60,
    confidence:                 ai.confidence                 || 0,
    tags:                       ai.tags                       || [ticket.category.toLowerCase()],
    similar_fix:                ai.similar_fix                || null,
    used_fallback:              Object.keys(ai).length === 0
  }
};

return [{ json: enriched }];

