// ═══════════════════════════════════════════════════════════════
// NODE: FORMAT JIRA ATLASSIAN DOCUMENT FORMAT (ADF)
// Builds a rich Jira ticket with AI analysis, KB context,
// recommended actions, technical context, and missing-field alerts.
// ═══════════════════════════════════════════════════════════════

const t = $input.first().json;

const PRI = { CRITICAL:'Highest', HIGH:'High', MEDIUM:'Medium', LOW:'Low', INFO:'Lowest' };
const TYP = { CRITICAL:'Incident', HIGH:'Incident', MEDIUM:'Task', LOW:'Task', INFO:'Task' };

// Build ADF action list items
const actionItems = (t.ai.recommended_actions||[]).map(a => ({
  type:'listItem',
  content:[{type:'paragraph',content:[{type:'text',text:a}]}]
}));

// KB section if matches exist
const kbSection = t.kb_similar?.length > 0 ? [
  { type:'heading', attrs:{level:3}, content:[{type:'text',text:'📚 Similar Past Incidents (Knowledge Base)'}] },
  ...t.kb_similar.slice(0,2).map(inc => ({
    type:'paragraph',
    content:[{type:'text',text:`• ${inc.title} → Fix: ${inc.resolution_summary||'See KB'}`}]
  }))
] : [];

// Missing data warning
const missingSection = t.data_quality.missing_fields.length > 0 ? [{
  type:'paragraph',
  content:[{type:'text',text:`⚠️ Auto-filled fields (verify): ${t.data_quality.missing_fields.join(', ')}`,marks:[{type:'strong'}]}]
}] : [];

const adf = {
  type:'doc', version:1,
  content:[
    { type:'heading', attrs:{level:2}, content:[{type:'text',text:'📋 Incident Overview'}] },
    { type:'paragraph', content:[{type:'text',text:t.ai.summary}] },

    { type:'heading', attrs:{level:3}, content:[{type:'text',text:'🤖 AI Analysis'}] },
    { type:'paragraph', content:[{type:'text',text:`Priority Score: ${t.ai.priority_score}/100 | Confidence: ${Math.round((t.ai.confidence||0)*100)}% | Est. Resolution: ${t.ai.estimated_resolution_min||60}min`}] },
    { type:'paragraph', content:[{type:'text',text:`Root Cause: ${t.ai.root_cause_hypothesis}`}] },
    { type:'paragraph', content:[{type:'text',text:`Assigned Team: @${t.ai.recommended_team}`}] },

    { type:'heading', attrs:{level:3}, content:[{type:'text',text:'✅ Recommended Actions'}] },
    { type:'bulletList', content: actionItems },

    ...kbSection,

    { type:'heading', attrs:{level:3}, content:[{type:'text',text:'🛠 Technical Context'}] },
    { type:'paragraph', content:[{type:'text',text:`Source: ${t.source} | Env: ${t.environment} | Region: ${t.region} | Cluster: ${t.cluster} | NS: ${t.namespace}`}] },
    { type:'paragraph', content:[{type:'text',text:`Services: ${t.affected_services.join(', ')} | Reporter: ${t.reporter.name} <${t.reporter.email}>`}] },
    { type:'paragraph', content:[{type:'text',text:`SLA Deadline: ${t.sla_deadline} | Escalation At: ${t.escalation_deadline}`}] },

    ...missingSection
  ]
};

return [{ json: {
  ...t,
  jira_payload: {
    fields: {
      project:    { key: process.env.JIRA_PROJECT_KEY || 'DEVOPS' },
      summary:    `[${t.severity}][${t.source}][${t.category}] ${t.title.slice(0,200)}`,
      description: adf,
      issuetype:  { name: TYP[t.severity]||'Task' },
      priority:   { name: PRI[t.severity]||'Medium' },
      labels:     ['automated', t.source.toLowerCase(), t.category.toLowerCase(), t.severity.toLowerCase(), t.environment, ...(t.ai.tags||[]).slice(0,4)]
    }
  }
}}];

const ticket = $input.first().json;
const jiraKey = ticket.key || ticket.id || null;
const base    = process.env.JIRA_BASE_URL || 'https://company.atlassian.net';
return [{ json: {
  ...ticket,
  jira_issue_key: jiraKey,
  jira_url:       jiraKey ? `${base}/browse/${jiraKey}` : null
}}];

const t  = $input.first().json;
const SE = { CRITICAL:'🔴', HIGH:'🟠', MEDIUM:'🟡', LOW:'🔵', INFO:'⚪' };
const CE = { DEPLOYMENT:'🚀', INFRASTRUCTURE:'🏗', SECURITY:'🔒', PERFORMANCE:'⚡', DATABASE:'🗄', NETWORK:'🌐', APPLICATION:'💻' };

const ch = t.severity==='CRITICAL' ? '#incidents-critical' :
           t.severity==='HIGH'     ? '#incidents-high'     : '#devops-tickets';

const rollbackBlock = t.ai.requires_rollback ? [{
  type:'section',
  text:{type:'mrkdwn',text:`⚠️ *Rollback Requested* for \`${t.ai.rollback_target}\` — awaiting human approval in #incident-approvals`}
}] : [];

const kbBlock = t.kb_similar?.length>0 ? [{
  type:'context',
  elements:[{type:'mrkdwn',text:`📚 ${t.kb_similar.length} similar past incident(s) found in knowledge base`}]
}] : [];

const missingBlock = t.data_quality.missing_fields.length>0 ? [{
  type:'context',
  elements:[{type:'mrkdwn',text:`⚠️ Auto-filled fields: ${t.data_quality.missing_fields.join(', ')}`}]
}] : [];

const blocks = [
  { type:'header', text:{type:'plain_text',text:`${SE[t.severity]} ${t.severity} — ${t.ticket_id}`} },
  { type:'section', fields:[
    {type:'mrkdwn',text:`*Title:*\n${t.title.slice(0,100)}`},
    {type:'mrkdwn',text:`*Category:*\n${CE[t.category]||''} ${t.category}`},
    {type:'mrkdwn',text:`*Source:*\n${t.source}`},
    {type:'mrkdwn',text:`*Environment:*\n\`${t.environment}\``},
    {type:'mrkdwn',text:`*Team:*\n@${t.ai.recommended_team}`},
    {type:'mrkdwn',text:`*SLA:*\n${new Date(t.sla_deadline).toUTCString()}`}
  ]},
  { type:'section', text:{type:'mrkdwn',text:`*🤖 AI Summary:*\n${t.ai.summary}`} },
  { type:'section', text:{type:'mrkdwn',text:`*Root Cause:* ${t.ai.root_cause_hypothesis}`} },
  { type:'section', text:{type:'mrkdwn',text:`*Actions:*\n${t.ai.recommended_actions.map((a,i)=>`${i+1}. ${a}`).join('\n')}`} },
  ...rollbackBlock,
  ...kbBlock,
  ...missingBlock,
  {
    type:'actions',
    elements:[
      t.jira_url ? {type:'button',text:{type:'plain_text',text:'🎫 Jira Issue'},url:t.jira_url,style:'primary'} : null,
      {type:'button',text:{type:'plain_text',text:'📖 Runbook'},url:`https://runbooks.company.com/${t.category.toLowerCase()}`}
    ].filter(Boolean)
  },
  {type:'divider'},
  {type:'context',elements:[{type:'mrkdwn',text:`Services: \`${t.affected_services.join('\`, \`')}\` | Cluster: \`${t.cluster}\` | Confidence: ${Math.round((t.ai.confidence||0)*100)}% | Quality: ${t.data_quality.completeness_score}%`}]}
];

return [{ json: { ...t, slack_payload:{ channel:ch, text:`${SE[t.severity]} [${t.severity}] ${t.ticket_id} — ${t.title.slice(0,80)}`, blocks } } }];

// ═══════════════════════════════════════════════════════════════
// NODE: FINAL STRUCTURED OUTPUT
// Assembles the canonical ticket record for database storage,
// audit logging, and downstream system consumption.
// ═══════════════════════════════════════════════════════════════

const t   = $input.first().json;
const now = new Date().toISOString();

const record = {
  // Identity
  ticket_id:      t.ticket_id,
  jira_issue_key: t.jira_issue_key || null,
  jira_url:       t.jira_url       || null,
  status:         'OPEN',

  // Core ticket
  title:             t.title,
  description:       t.description,
  source:            t.source,
  severity:          t.severity,
  category:          t.category,
  environment:       t.environment,
  region:            t.region,
  cluster:           t.cluster,
  namespace:         t.namespace,
  affected_services: t.affected_services,
  reporter:          t.reporter,

  // Timestamps & SLA
  reported_at:         t.reported_at,
  ingested_at:         t.ingested_at,
  processed_at:        now,
  sla_deadline:        t.sla_deadline,
  escalation_deadline: t.escalation_deadline,
  sla_breach_risk:     new Date(t.sla_deadline) < new Date(Date.now() + 3600000),

  // AI enrichment
  ai_analysis: t.ai,

  // Knowledge base
  kb_similar_count: (t.kb_similar||[]).length,
  kb_similar_ids:   (t.kb_similar||[]).map(i=>i.id).filter(Boolean),

  // Workflow execution summary
  workflow_actions: {
    jira_created:       Boolean(t.jira_issue_key),
    slack_notified:     true,
    rollback_requested: t.ai.requires_rollback,
    rollback_approved:  t._rollback_approved || false,
    rollback_executed:  t._rollback_executed || false,
    oncall_escalated:   t.ai.escalate_to_oncall
  },

  // Data quality
  data_quality: t.data_quality,
  metadata:     t.metadata,

  schema_version: '3.0.0',
  processed_by:   'n8n-enterprise-workflow'
};

return [{ json: record }];

